### popup.js

```js
const form = document.getElementById('profileForm');
const status = document.getElementById('status');

form.addEventListener('submit', e => {
  e.preventDefault();

  const gender = document.getElementById('gender').value;
  const income = document.getElementById('income').value;
  const ethnicity = document.getElementById('ethnicity').value;

  if (!gender || !income || !ethnicity) {
    status.textContent = 'Please fill all fields!';
    return;
  }

  // Save user profile in chrome.storage
  chrome.storage.sync.set({ userProfile: { gender, income, ethnicity } }, () => {
    status.textContent = 'Profile saved!';
  });
});

// Load saved profile on popup open
window.onload = () => {
  chrome.storage.sync.get('userProfile', data => {
    if (data.userProfile) {
      document.getElementById('gender').value = data.userProfile.gender;
      document.getElementById('income').value = data.userProfile.income;
      document.getElementById('ethnicity').value = data.userProfile.ethnicity;
    }
  });
};
```

