  let price = basePrice;

  // Example rules - adjust price (+ or - %) 
  if (gender === 'female') price = price * 0.95; 
  if (income === 'high') price = price * 1.10;
  if (ethnicity === 'ethnicity2') price = price * 0.90;

  return price.toFixed(2);
}

function displayPrices(userProfile) {
  storeItems.forEach(item => {
    // Find element for this item price on page by id or class
    // For demo, suppose elements have id like price-item1, price-item2
    const priceElement = document.getElementById(`price-${item.id}`);

    if (priceElement) {
      const adjustedPrice = adjustPrice(item.basePrice, userProfile.gender, userProfile.income, userProfile.ethnicity);
      priceElement.textContent = `$${adjustedPrice}`;
    }
  });
}

// Load user profile from storage and update prices
chrome.storage.sync.get('userProfile', data => {
  if (data.userProfile) {
    displayPrices(data.userProfile);
  }
});
